patch:
diff --git a/repro/eslint.config.js b/repro/eslint.config.js
new file mode 100644
index 0000000..c3361b3
--- /dev/null
+++ b/repro/eslint.config.js
@@ -0,0 +1,8 @@
+module.exports = [
+  {
+    files: ["**/*.js"],
+    rules: {
+      "no-useless-assignment": "warn"
+    },
+  },
+];
diff --git a/repro/report.js b/repro/report.js
new file mode 100644
index 0000000..f5bbb99
--- /dev/null
+++ b/repro/report.js
@@ -0,0 +1,14 @@
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
diff --git a/repro/run-report.js b/repro/run-report.js
new file mode 100644
index 0000000..3bff2bc
--- /dev/null
+++ b/repro/run-report.js
@@ -0,0 +1,21 @@
+// Runs the reporter's sample through the checked-out ESLint (lib/api.js),
+// using the reporter's flat config (only no-useless-assignment: "warn").
+"use strict";
+const path = require("node:path");
+const fs = require("node:fs");
+const { ESLint } = require("../lib/api");
+
+(async () => {
+    const eslint = new ESLint({ cwd: __dirname, overrideConfigFile: path.join(__dirname, "eslint.config.js") });
+    const [result] = await eslint.lintFiles([path.join(__dirname, "report.js")]);
+    const src = fs.readFileSync(path.join(__dirname, "report.js"), "utf8").split("\n");
+    console.log(`ESLint ${ESLint.version}`);
+    for (const m of result.messages) {
+        console.log(`${m.line}:${m.column} ${m.ruleId} ${m.message}\n    > ${src[m.line - 1].trim()}`);
+    }
+    const bug = result.messages.some(m => m.ruleId === "no-useless-assignment" && m.line === 4);
+    console.log(bug
+        ? "BUG REPRODUCED: `intermediaryValue = 42` flagged although it is read in the catch block"
+        : "not reproduced: no report on line 4");
+    process.exitCode = bug ? 1 : 0;
+})();
diff --git a/repro/variants.js b/repro/variants.js
new file mode 100644
index 0000000..0e3b615
--- /dev/null
+++ b/repro/variants.js
@@ -0,0 +1,15 @@
+// Narrows the trigger: same assignment-in-try / read-in-catch shape, varying what ends the try block.
+"use strict";
+const { Linter } = require("../lib/api");
+const linter = new Linter();
+const cases = {
+    "reporter (return in try)": `function fn() { let v; try { v = 42; unsafeFn(); return 1; } catch { return v; } }`,
+    "no return in try": `function fn() { let v; try { v = 42; unsafeFn(); } catch { return v; } }`,
+    "throw in try": `function fn() { let v; try { v = 42; unsafeFn(); throw 1; } catch { return v; } }`,
+    "break in try (loop)": `function fn() { let v; for (;;) { try { v = 42; unsafeFn(); break; } catch { return v; } } }`,
+    "read in finally, return in try": `function fn() { let v; try { v = 42; unsafeFn(); return 1; } finally { console.log(v); } }`,
+};
+for (const [name, code] of Object.entries(cases)) {
+    const msgs = linter.verify(code, { rules: { "no-useless-assignment": "error" } });
+    console.log(`${msgs.length ? "FLAGGED " : "ok      "} ${name}${msgs.map(m => `  [${m.column}: ${m.message}]`).join("")}`);
+}
